rgin:12px 0}.inline label{min-width:240px}.box{border:1px solid #c4c4bf;background:#f2f2ef;padding:19px;margin-top:24px}.box h3{margin-top:0}.box label{margin-bottom:15px}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.metric{background:#fafaf8;border:1px solid #c4c4bf;padding:15px}.metric strong{display:block;font-size:22px}.metric span{font-size:12px;color:#55554f}pre{font:12px/1.6 ui-monospace,SFMono-Regular,Consolas,monospace;padding:15px;border:1px solid #c4c4bf;background:#f2f2ef;white-space:pre-wrap;overflow-wrap:anywhere;max-height:420px;overflow:auto}code{font:12px ui-monospace,SFMono-Regular,Consolas,monospace}table{border-collapse:collapse;width:100%;font-size:12px;background:#fff}th,td{padding:9px 11px;border:1px solid #cfcec7;text-align:left;vertical-align:top;max-width:420px;overflow-wrap:anywhere}th{background:#e9e9e5;font-weight:650}tbody tr:nth-child(even){background:#f6f6f3}.table-wrap{overflow:auto;margin:15px 0;max-height:550px}#message:not(:empty){padding:12px 16px;border:1px solid #55554f;margin-bottom:18px;background:#fff}#message.error{border:2px solid #2b2b2b;font-weight:600}.metadata{padding:14px;border:1px solid #ccc;white-space:pre-wrap}footer{padding:18px 36px;color:#63635e;font-size:12px;border-top:1px solid #c4c4bf}[hidden]{display:none!important}@media(max-width:760px){header{padding:20px;flex-direction:column}main{padding:16px}nav{padding:0 8px}.form-grid{grid-template-columns:1fr}section[data-panel]{padding:17px}.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.inline{align-items:stretch;flex-direction:column}.inline label{min-width:0}button{min-height:42px}footer{padding:18px}}\n\n.source-notice{font-size:.85rem;line-height:1.5;color:#444;padding:0 2rem;max-width:100rem;margin:1rem auto}.source-notice a{color:inherit;text-decoration:underline}\n\n.briefing-editor{margin:20px 0;padding:18px 0;border-top:1px solid #bcbcb8;border-bottom:1px solid #bcbcb8}.check{display:flex;flex-direction:row;gap:8p