      "content": "// MIT. Native x402 settlement -> durable minimal merchant delivery event.\n// This does not verify payments: ONLY the original SF30 native server can do so.\nimport { createHash } from 'node:crypto';\nimport { constants } from 'node:fs';\nimport { mkdir, open, readFile, stat } from 'node:fs/promises';\nimport { isAbsolute, join, resolve } from 'node:path';\nimport { selectServiceRoute } from '../sf30-seller-sdk/route-path.mjs';\nimport { supportsSellerMethod } from '../sf30-seller-sdk/http-methods.mjs';\n\nexport const SCHEMA = 'stellar-forge.sf98.delivery-event.v1';\nconst hash = x => createHash('sha256').update(x).digest('hex');\nconst okId = x => typeof x === 'string' && /^[a-f0-9]{64}$/.test(x);\nconst date = () => new Date().toISOString();\nconst nativeInstrumentations = new WeakMap();\n\n/** Original embedding metadata for a later managed launcher. Payment callers\n * receive the same server; observers see only the original journal warning. */\nexport function inspectNativeSettlementInstrumentation(server) {\n  const held = nativeInstrumentations.get(server);\n  if (!held) return null;\n  return Object.freeze({ server, outbox: held.outbox,\n    observeWriteFailures(listener) {\n      if (typeof listener !== 'function') throw new TypeError('Native delivery warning observer required');\n      held.observers.add(listener); return () => held.observers.delete(listener);\n    } });\n}\n\nfunction parseLine(line, path, index) {\n  let data;\n  try { data = JSON.parse(line); } catch { throw new Error('CORRUPT_JOURNAL:' + path + ':' + index); }\n  if (!data || typeof data !== 'object' || !okId(data.id)) throw new Error('INVALID_JOURNAL_RECORD:' + path + ':' + index);\n  return data;\n}\nasync function loadLines(path) {\n  let data;\n  try { data = await readFile(path, 'utf8'); }\n  catch (e) { if (e.code === 'ENOENT') return []; throw e; }\n  if (data && !data.endsWith('\\n')) throw new Error('TRUNCATED_JOURNAL:' + path);\n  return data.split('\\n').