      "content": "// MIT. Research catalogue semantics for the original economic project.\nimport { createHash } from 'node:crypto';\nexport const SCHEMA='stellar-forge.research-catalog.v1';\nexport const CAPTURE='stellar-forge.research-source.v1';\nexport const MAX_SOURCE_BYTES=16*1024*1024;\nexport const MAX_TOTAL_BYTES=128*1024*1024;\nexport function need(ok,message,code='RESEARCH_INVALID',status=400){if(!ok)throw Object.assign(new Error(message),{code,status});}\nexport const plain=v=>v!==null&&typeof v==='object'&&!Array.isArray(v);\nexport function canonical(v){if(v===null||['string','boolean'].includes(typeof v))return JSON.stringify(v);if(typeof v==='number'&&Number.isFinite(v))return JSON.stringify(v);if(Array.isArray(v))return '['+v.map(canonical).join(',')+']';need(plain(v),'Use complete JSON values.');return '{'+Object.keys(v).sort().map(k=>JSON.stringify(k)+':'+canonical(v[k])).join(',')+'}';}\nexport const sha=bytes=>createHash('sha256').update(bytes).digest('hex');\nexport const digest=value=>sha(Buffer.from(canonical(value)));\nexport const clone=value=>JSON.parse(JSON.stringify(value));\nexport function text(v,max=1000,required=false){need(typeof v==='string'&&v.length<=max&&(!required||v.trim()),'Enter complete text within its stated capacity.');need(!/[\\u0000-\\u0008\\u000b\\u000c\\u000e-\\u001f]/.test(v),'Remove control characters from text.');return v.trim();}\nexport function key(v){const s=text(v,160,true);need(/^[A-Za-z0-9][A-Za-z0-9_.:-]*$/.test(s),'Use a stable letter/number source identity.');return s;}\nexport function instant(v){need(typeof v==='string'&&/^\\d{4}-\\d\\d-\\d\\dT/.test(v)&&Number.isFinite(Date.parse(v)),'Use the original timestamp with its time zone.');return new Date(v).toISOString();}\nexport function day(v){if(v===null||v===undefined||v==='')return null;need(typeof v==='string'&&/^\\d{4}-\\d\\d-\\d\\d$/.test(v)&&Number.isFinite(Date.parse(v+'T00:00:00Z'))&&new Date(v+'T00:00:00Z').toISOString().slice(0,10)===v,'Use a valid calendar date.');return v;}\nexport function url(v){const s=text(v,4000,true);let u;try{u=new URL(s);}catch{need(false,'Use an absolute source URL.');}need(['http:','https:'].includes(u.protocol)&&!u.username&&!u.password,'Use an ordinary source URL without credentials.');return u.href;}\nexport function tags(v){need(Array.isArray(v)&&v.length<=100,'Use up to100 explicit taxonomy values.');const a=v.map(x=>text(x,160,true));need(new Set(a).size===a.length,'Keep taxonomy values unique.');return a.slice().sort();}\nfunction keys(v,allowed){need(plain(v)&&Object.keys(v).every(k=>allowed.includes(k)),'The source record contains unsupported fields.');}\nexport function definition(v){keys(v,['entryId','title','publisher','url','kind','topics','geographies','cadenceDays','expectedRelease','licence','notes','retired']);\nconst kind=text(v.kind,40,true);need(['DATASET','RESEARCH','REPORT','METHOD','OTHER'].includes(kind),'Choose a dataset, research, report, method or other source.');\nconst cadenceDays=v.cadenceDays??null;need(cadenceDays===null||(Number.isInteger(cadenceDays)&&cadenceDays>=1&&cadenceDays<=3660),'Use an explicit refresh interval or leave it unassigned.');\nreturn {entryId:key(v.entryId),title:text(v.title,500,true),publisher:text(v.publisher,500,true),url:url(v.url),kind,topics:tags(v.topics??[]),geographies:tags(v.geographies??[]),cadenceDays,expectedRelease:day(v.expectedRelease),licence:text(v.licence??'',4000),notes:text(v.notes??'',12000),retired:v.retired===true};}\nexport function catalogue(state){return state.research??{schema:SCHEMA,entries:[],sources:[],reviews:[],products:[]};}\nexport function currentDefinition(cat,entryId){const entry=cat.entries.find(x=>x.id===entryId);need(entry,'Select an original catalogue entry.');return entry.versions.find(v=>v.id===entry.currentId);}\nexport function normalizeCapture(value){keys(value,['schema','entryId','definitionId','requestedUrl','finalUrl','retrievedAt','status','contentType','filename','headers','bodyBase64','bytes','sha256','id','mode']);\nneed(value.schema===CAPTURE,'Retain the original source capture.');const bytes=Buffer.from(text(value.bodyBase64,Math.ceil(MAX_SOURCE_BYTES/3)*4+4), 'base64');\nneed(bytes.toString('base64')===value.bodyBase64&&bytes.length<=MAX_SOURCE_BYTES,'The complete original source exceeds16MiB or its encoding changed.');\nneed(value.bytes===bytes.length&&value.sha256===sha(bytes),'Original source bytes or hash changed.');need(Number.isInteger(value.status)&&value.status>=100&&value.status<=599,'Retain the original HTTP status.');\nneed(typeof value.contentType==='string'&&/^[a-zA-Z0-9!#$%&'*+.^_`|~-]+\\/[a-zA-Z0-9!#$%&'*+.^_`|~-]+(?:;[^\\r\\n]*)?$/.test(value.contentType),'Use a complete media type without header controls.');const headers=value.headers??{};keys(headers,['content-type','content-length','content-encoding','etag','last-modified','date','location']);for(const v of Object.values(headers))text(v,4000);\nneed(/^[a-f0-9]{64}$/.test(value.definitionId),'Retain the exact source definition.');\nconst filename=text(value.filename??'source.bin',180,true);need(!/[\\\\/\\r\\n]/.test(filename)&&!['.','..'].includes(filename),'Use one source filename.');\nneed(['HTTP','UPLOAD'].includes(value.mode),'Record how the source was received.');\nconst normalized={schema:CAPTURE,entryId:key(value.entryId),definitionId:value.definitionId,requestedUrl:url(value.requestedUrl),finalUrl:url(value.finalUrl),retrievedAt:instant(value.retrievedAt),status:value.status,contentType:text(value.contentType??'application/octet-stream',250,true),filename,headers:clone(headers),mode:value.mode,bodyBase64:value.bodyBase64,bytes:bytes.length,sha256:sha(bytes)};\nconst id=digest(normalized);need(value.id===id,'Original capture identity changed.');return normalized&&{...normalized,id};}\nexport function makeCapture({entry,definitionId,retrievedAt,status=200,finalUrl,contentType='application/octet-stream',filename='source.bin',headers={},bytes,mode='UPLOAD'}){\nneed(Buffer.isBuffer(bytes)&&bytes.length<=MAX_SOURCE_BYTES,'Retain complete source bytes within16MiB.');const value={schema:CAPTURE,entryId:entry.entryId,definitionId,requestedUrl:entry.url,finalUrl:finalUrl??entry.url,retrievedAt:instant(retrievedAt),status,contentType,filename,headers,mode,bodyBase64:bytes.toString('base64'),bytes:bytes.length,sha256:sha(bytes)};return normalizeCapture({...value,id:digest(value)});}\nexport function sourceSummary(capture){const {bodyBase64,headers,...summary}=normalizeCapture(capture);return summary;}\nexport function normalizeProduct(v){keys(v,['productId','title','audience','purpose','format','notes','requirements','retired']);\nneed(Array.isArray(v.requirements)&&v.requirements.length>=1&&v.requirements.length<=100,'Give the research product1–100 explicit source requirements.');\nconst requirements=v.requirements.map(r=>{keys(r,['id','title','entryIds','topics','geographies','note']);need(Array.isArray(r.entryIds)&&r.entryIds.length<=100,'Select explicit original source entries.');const entryIds=r.entryIds.map(key);need(new Set(entryIds).size===entryIds.length,'Use each selected source once per requirement.');return {id:key(r.id),title:text(r.title,500,true),entryIds:entryIds.sort(),topics:tags(r.topics??[]),geographies:tags(r.geographies??[]),note:text(r.note??'',4000)};});\nneed(new Set(requirements.map(r=>r.id)).size===requirements.length,'Keep requirement identities unique.');\nreturn {productId:key(v.productId),title:text(v.title,500,true),audience:text(v.audience??'',2000),purpose:text(v.purpose??'',12000),format:text(v.format??'',2000),notes:text(v.notes??'',12000),requirements,retired:v.retired===true};}\nexport function latestSource(cat,entryId,definitionId){return cat.sources.filter(s=>s.entryId===entryId&&s.definitionId===definitionId).at(-1)??null;}\nexport function latestReview(cat,snapshotId){return cat.reviews.filter(r=>r.snapshotId===snapshotId).at(-1)??null;}\nexport function sourceStatus(cat,entryId,asOf