      "content": "// MIT. Full catalogue and original source files travel in the economic project.\nimport { join, resolve } from 'node:path';\nimport { privateDirectory, atomicJson, readPrivateJson } from '../../routescan/quota.mjs';\nimport { need, catalogue, canonical, normalizeCapture, sourceSummary, validateResearchState, MAX_SOURCE_BYTES, MAX_TOTAL_BYTES } from './model.mjs';\nconst LIMIT=Math.ceil(MAX_SOURCE_BYTES/3)*4+128000;\nexport function validateResearchExtension(value,state){validateResearchState(state);if(state.research===undefined){need(value===undefined||value===null,'Unexpected research sources in project.');return null;}\nneed(value?.schema==='stellar-forge.research-source-bundle.v1'&&Array.isArray(value.sources),'Receive the complete research source bundle.');const cat=catalogue(state);need(value.sources.length===cat.sources.length&&new Set(value.sources.map(c=>c.id)).size===cat.sources.length,'Keep every original research source once.');\nlet total=0;for(const v of value.sources){const c=normalizeCapture(v),s=cat.sources.find(s=>s.id===c.id),entry=cat.entries.find(e=>e.id===c.entryId),definition=entry?.versions.find(v=>v.id===c.definitionId);need(s&&canonical(s)===canonical(sourceSummary(c))&&definition?.definition.url===c.requestedUrl,'The original source metadata or definition differs.');total+=c.bytes;}need(total<=MAX_TOTAL_BYTES,'The complete research source bundle exceeds128MiB.');return value;}\nexport async function exportResearchExtension(directory,state){if(state.research===undefined)return null;const sources=[];for(const s of catalogue(state).sources)sources.push(await readPrivateJson(join(resolve(directory),'research','sources',s.id+'.json'),LIMIT));const value={schema:'stellar-forge.research-source-bundle.v1',sources};validateResearchExtension(value,state);return value;}\nexport async function receiveResearchExtension(directory,value,state){const validated=validateResearchExtension(value,state);if(!validated)return;const root=await privateDirectory(join(resolve(directory),'research','sources'));for(const source of validated.sources){const name=source.id+'.json';let previous;try{previous=await readPrivateJson(join(root,name),LIMIT);}catch(e){if(e.code!=='ENOENT')throw e;}if(previous)need(canonical(normalizeCapture(previous))===canonical(source),'A retained receiving source changed.');else await atomicJson(root,name,source,{exclusive:true});}}\n",
