      "content": "// MIT. Retain the complete response from one explicitly selected public source.\nimport https from 'node:https';\nimport http from 'node:http';\nimport { lookup } from 'node:dns/promises';\nimport { isIP } from 'node:net';\nimport { need, url, MAX_SOURCE_BYTES } from './model.mjs';\nfunction publicAddress(address){const ip=address.toLowerCase();if(isIP(ip)===4){const a=ip.split('.').map(Number);return !(a[0]===0||a[0]===10||a[0]===127||a[0]>=224||(a[0]===100&&a[1]>=64&&a[1]<=127)||(a[0]===169&&a[1]===254)||(a[0]===172&&a[1]>=16&&a[1]<=31)||(a[0]===192&&a[1]===168)||(a[0]===198&&[18,19].includes(a[1])));}\nif(isIP(ip)===6)return !ip.startsWith('::')&&!ip.startsWith('fc')&&!ip.startsWith('fd')&&!/^fe[89ab]/.test(ip)&&!ip.startsWith('ff');return false;}\nasync function response(source,{signal}){\nconst target=new URL(source);need(['http:','https:'].includes(target.protocol)&&!target.username&&!target.password&&!target.hash,'Choose an ordinary complete source URL without credentials or a fragment.');need(!target.port||target.port===(target.protocol==='https:'?'443':'80'),'Use the publisher’s standard public web port.');\nconst addresses=await lookup(target.hostname,{all:true,verbatim:true});need(addresses.length&&addresses.every(v=>publicAddress(v.address)),'Choose a public publisher source; private network addresses are not fetched.');\nreturn new Promise((accept,reject)=>{const client=target.protocol==='https:'?https:http;let done=false;\nconst request=client.request(target,{method:'GET',signal,timeout:30000,headers:{accept:'*/*','accept-encoding':'identity','user-agent':'Research source receiving/1.0'},lookup:(host,options,callback)=>{const selected=options?.family?addresses.filter(a=>a.family===options.family):addresses;if(!selected.length)return callback(new Error('The original public source address family is unavailable.'));if(options?.all)callback(null,selected);else callback(null,selected[0].address,selected[0].family);}},res=>{\nconst chunks=[];let length=0;res.on('data',chunk=>{length+=chunk.length;if(length>MAX_SOURCE_BYTES){res.destroy(Object.assign(new Error('Original source exceeds16MiB; retain a selected complete source edition through its native collection workflow.'),{code:'RESEARCH_SOURCE_TOO_LARGE',status:413}));return;}chunks.push(chunk);});\nres.on('error',reject);res.on('end',()=>{if(done)return;done=true;const headers={};for(const name of ['content-type','content-length','content-encoding','etag','last-modified','date','location']){const v=res.headers[name];if(typeof v==='string')headers[name]=v.slice(0,4000);}accept({status:res.statusCode,headers,bytes:Buffer.concat(chunks,length)});});});request.on('timeout',()=>request.destroy(Object.assign(new Error('The original source timed out.'),{code:'RESEARCH_SOURCE_TIMEOUT',status:504})));request.on('error',reject);request.end();});}\nexport async function acquirePublicResearchSource(selected,{signal}={}){const original=url(selected),origin=new URL(original).origin;let selectedUrl=new URL(original);selectedUrl.hash='';let current=selectedUrl.href;for(let redirects=0;redirects<=3;redirects++){const result=await response(current,{signal});if([301,302,303,307,308].includes(result.status)&&result.headers.location){const next=new URL(result.headers.location,current);if(next.origin===origin&&redirects<3){current=next.href;continue;}}\nconst contentType=(result.headers['content-type']??'application/octet-stream').split(';')[0].trim().toLowerCase();need(/^[a-z0-9!#$&^_.+-]+\\/[a-z0-9!#$&^_.+-]+$/.test(contentType),'The returned source media type is invalid.');\nconst suffix=contentType==='application/pdf'?'pdf':contentType.includes('html')?'html':contentType.includes('json')?'json':contentType.includes('csv')?'csv':'bin';\nreturn {...result,contentType,filename:'original-source.'+suffix+(result.headers['content-encoding']&&result.headers['content-encoding']!=='identity'?'.encoded':''),finalUrl:current};}need(false,'The source exceeded three same-origin redirects.');}\n",
