      "content": "// MIT. Research source catalogue inside the original economic workspace.\nexport function mountFredResearch({api,download,getState,getBusy,refresh,message}){\nconst root=document.getElementById('research-workspace');if(!root)return {onState(){}};\nroot.innerHTML='<h2>Research sources and products</h2><p>Maintain the full source inventory, review original editions and carry the selected research products into the complete project handover.</p>'+\n'<div class=\"buttons\"><button id=\"research-reload\">Refresh catalogue</button><button id=\"research-export-csv\">Download source catalogue</button><button id=\"research-export-project\">Export complete project</button><button id=\"research-resume\">Continue original catalogue action</button></div>'+\n'<p id=\"research-summary\" role=\"status\"></p><form id=\"research-filter\" class=\"form-grid\"><label>Search<input id=\"research-query\"></label><label>Topic<select id=\"research-topic\"></select></label><label>Geography<select id=\"research-geography\"></select></label><label>Review status<select id=\"research-status\"><option value=\"\">All states</option><option>SOURCE_NEEDED</option><option>REVIEW_NEEDED</option><option>APPROVED</option><option>NEEDS_WORK</option><option>REJECTED</option><option>SOURCE_UNAVAILABLE</option><option>RETIRED</option></select></label><label class=\"check\"><input type=\"checkbox\" id=\"research-due\">Refresh due</label><button type=\"submit\">Apply filters</button></form>'+\n'<div id=\"research-table\" class=\"table-wrap\"></div><div class=\"buttons\"><button id=\"research-prev\">Previous page</button><button id=\"research-next\">Next page</button></div>'+\n'<details open><summary>Source record</summary><form id=\"research-entry-form\" class=\"form-grid\"><label>Stable source ID<input id=\"research-entry-id\" required maxlength=\"160\"></label><label>Title<input id=\"research-title\" required maxlength=\"500\"></label><label>Publisher<input id=\"research-publisher\" required maxlength=\"500\"></label><label>Source URL<input id=\"research-url\" type=\"url\" required></label><label>Kind<select id=\"research-kind\"><option>DATASET</option><option>RESEARCH</option><option>REPORT</option><option>METHOD</option><option>OTHER</option></select></label><label>Refresh interval, days<input id=\"research-cadence\" type=\"number\" min=\"1\" max=\"3660\"></label><label>Expected next release<input id=\"research-expected\" type=\"date\"></label><label class=\"check\"><input id=\"research-retired\" type=\"checkbox\">Retired source</label><label>Topics, one per line<textarea id=\"research-topics\" rows=\"3\"></textarea></label><label>Geographies, one per line<textarea id=\"research-geographies\" rows=\"3\"></textarea></label><label class=\"wide\">Source rights or licence<textarea id=\"research-licence\" rows=\"2\"></textarea></label><label class=\"wide\">Method and coverage notes<textarea id=\"research-notes\" rows=\"4\"></textarea></label><div class=\"buttons wide\"><button type=\"submit\">Save source definition</button><button type=\"button\" id=\"research-new\">New source</button></div></form>'+\n'<form id=\"research-import\" class=\"box\"><h3>Import source inventory</h3><p>Use the complete catalogue CSV header from Download source catalogue, or a JSON array of source definitions. Existing IDs receive new retained definitions.</p><label>Complete inventory file<input id=\"research-import-file\" type=\"file\" accept=\".csv,.json\" required></label><button>Import selected inventory</button></form></details>'+\n'<details open><summary>Original source and review</summary><p id=\"research-selected\">Open a catalogue source to retain or review its original file.</p><div class=\"buttons\"><button id=\"research-acquire\">Retrieve published source</button></div><form id=\"research-upload\" class=\"form-grid\"><label>Original retained source file<input id=\"research-upload-file\" type=\"file\" required></label><label>Original retrieval time<input id=\"research-upload-time\" type=\"datetime-local\"></label><button>Retain original file</button></form><div id=\"research-source-history\" class=\"table-wrap\"></div><form id=\"research-review\" class=\"form-grid\"><label>Original source edition<select id=\"research-review-source\" required></select></label><label>Reviewer<input id=\"research-reviewer\" maxlength=\"200\" required autocomplete=\"name\"></label><label>Decision<select id=\"research-decision\"><option>ACCEPT</option><option>NEEDS_WORK</option><option>REJECT</option></select></label><label class=\"wide\">Decision and limitations<textarea id=\"research-review-note\" required maxlength=\"12000\" rows=\"3\"></textarea></label><button>Record review</button></form><div id=\"research-review-history\" class=\"table-wrap\"></div></details>'+\n'<details open><summary>Research products and source gaps</summary><label>Saved research product<select id=\"research-product-select\"></select></label><form id=\"research-product-form\" class=\"form-grid\"><label>Stable product ID<input id=\"research-product-id\" required maxlength=\"160\"></label><label>Title<input id=\"research-product-title\" required maxlength=\"500\"></label><label>Audience<textarea id=\"research-product-audience\" rows=\"2\"></textarea></label><label>Delivery format<textarea id=\"research-product-format\" rows=\"2\"></textarea></label><label class=\"wide\">Purpose<textarea id=\"research-product-purpose\" rows=\"3\"></textarea></label><label class=\"wide\">Product notes<textarea id=\"research-product-notes\" rows=\"3\"></textarea></label><label class=\"check\"><input id=\"research-product-retired\" type=\"checkbox\">Retired product</label><div class=\"wide\"><h3>Required sources</h3><p>Each requirement names the original source records and the topic/geography coverage that the reviewer expects.</p><div id=\"research-requirements\"></div><button type=\"button\" id=\"research-add-requirement\">Add source requirement</button></div><div class=\"buttons wide\"><button>Save research product</button><button type=\"button\" id=\"research-product-new\">New product</button></div></form><div id=\"research-coverage\" class=\"table-wrap\"></div><form id=\"research-issue\" class=\"form-grid\"><label>Issuing staff member<input id=\"research-issuer\" required maxlength=\"200\"></label><label>Edition note<textarea id=\"research-issue-note\" rows=\"2\"></textarea></label><button>Issue reviewed product edition</button></form><div id=\"research-product-history\" class=\"table-wrap\"></div></details>';\nconst $=id=>document.getElementById(id),list=value=>value.split(/\\r?\\n/).map(s=>s.trim()).filter(Boolean),unique=value=>[...new Set(list(value))],el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};\nlet projectId=null,view=null,entry=null,offset=0,generation=0,loading=0,readEntry=0,pending=null,lastStateRevision=null;\nfunction guard(id,version){return projectId===id&&getState()?.id===id&&generation===version;}\nfunction choice(control,items,desired=control.value){control.replaceChildren();for(const [value,label]of items){const option=el('option',label);option.value=value;control.append(option);}if(items.some(([v])=>v===desired))control.value=desired;}\nfunction displayTable(id,rows,columns,button){const holder=$(id);holder.replaceChildren();if(!rows.length){holder.append(el('p','No retained records.'));return;}const table=el('table'),head=el('thead'),tr=el('tr');for(const [key,label]of columns)tr.append(el('th',label));if(button)tr.append(el('th','Open'));head.append(tr);const body=el('tbody');for(const row of rows){const line=el('tr');for(const [key]of columns){const v=row[key];line.append(el('td',v===null||v===undefined?'—':typeof v==='object'?JSON.stringify(v):String(v)));}if(button){const cell=el('td'),b=el('button',button.label);b.type='button';b.addEventListener('click',()=>safe(()=>button.run(row)));cell.append(b);line.append(cell);}body.append(line);}table.append(head,body);holder.ap