quirements').append(field);}\nfunction productDefinition(){return {productId:$('research-product-id').value,title:$('research-product-title').value,audience:$('research-product-audience').value,purpose:$('research-product-purpose').value,format:$('research-product-format').value,notes:$('research-product-notes').value,retired:$('research-product-retired').checked,requirements:[...$('research-requirements').children].map(f=>Object.fromEntries([...f.querySelectorAll('[data-requirement]')].map(input=>[input.dataset.requirement,['entryIds','topics','geographies'].includes(input.dataset.requirement)?unique(input.value):input.value])))};}\nfunction renderProduct(){const product=view?.products.find(p=>p.id===$('research-product-select').value);displayTable('research-coverage',product?.coverage.map(r=>({id:r.id,title:r.title,state:r.state,sources:r.selected.map(s=>s.entryId+': '+s.status).join('; ')}))??[],[['id','Requirement'],['title','Title'],['state','Coverage'],['sources','Source decisions']]);displayTable('research-product-history',product?.editions??[],[['issuedAt','Issued'],['issuedBy','Staff'],['note','Edition note'],['id','Retained edition']]);}\nfunction openProduct(){const product=view?.products.find(p=>p.id===$('research-product-select').value);if(!product)return;const d=product.definition;for(const key of ['id','title','audience','purpose','format','notes'])$('research-product-'+key).value=d[key==='id'?'productId':key];$('research-product-id').readOnly=true;$('research-product-retired').checked=d.retired;$('research-requirements').replaceChildren();d.requirements.forEach(addRequirement);renderProduct();}\nevent('research-filter','submit',async()=>{offset=0;await load();});event('research-reload','click',load);event('research-prev','click',async()=>{offset=Math.max(0,offset-100);await load();});event('research-next','click',async()=>{if(view?.nextOffset!==null){offset=view.nextOffset;await load();}});\nevent('research-entry-form','submit',async()=>{const d=entryDefinition();await action('research-entry-save',{definition:d});await openEntry(d.entryId);message('Source definition retained.');});event('research-new','click',clearEntry);\nevent('research-import','submit',async()=>{const f=$('research-import-file').files[0];if(!f)throw new Error('Choose the complete inventory.');const content=await f.text();await action('research-import',f.name.toLowerCase().endsWith('.csv')?{csv:content}:{definitions:JSON.parse(content)});message('Selected source inventory retained.');});\nevent('research-acquire','click',async()=>{const result=await action('research-source-acquire',selectedEntry());message(result.status==='SOURCE_UNAVAILABLE'?'The publisher response is retained for review; its HTTP status is unavailable.':'The complete original source is retained for review.');});\nevent('research-upload','submit',async()=>{const selected=selectedEntry(),file=$('research-upload-file').files[0];if(!file)throw new Error('Choose the complete original file.');if(file.size>16*1024*1024)throw new Error('The complete original file exceeds16MiB.');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=16384)binary+=String.fromCharCode(...bytes.subarray(i,i+16384));const time=$('research-upload-time').value;await action('research-source-upload',{...selected,filename:file.name,contentType:file.type||'application/octet-stream',bodyBase64:btoa(binary),...(time?{retrievedAt:new Date(time).toISOString()}:{} )});message('Original file and source identity retained.');});\nevent('research-review','submit',async()=>{await action('research-review',{snapshotId:$('research-review-source').value,decision:$('research-decision').value,reviewer:$('research-reviewer').value,note:$('research-review-note').value});message('Review decision retained.');});\nevent('research-add-requirement','click',()=>addRequirement());event('research-product-select','change',openProduct);event('research-product-new','click',()=>{$('research-product-form').reset();$('research-product-id').readOnly=false;$('research-requirements').replaceChildren();addRequirement();$('research-product-select').value='';renderProduct();});\nevent('research-product-form','submit',async()=>{const d=productDefinition();await action('research-product-save',{definition:d});$('research-product-select').value=d.productId;openProduct();message('Research product and complete source requirements retained.');});\nevent('research-issue','submit',async()=>{const id=$('research-product-select').value;if(!id)throw new Error('Open a saved product.');await action('research-product-issue',{productId:id,issuedBy:$('research-issuer').value,note:$('research-issue-note').value});message('Reviewed research product edition issued with its original sources.');});\nevent('research-export-csv','click',()=>download('/api/research/catalog.csv','research-source-catalog.csv'));event('research-export-project','click',()=>download('/api/bundle','complete-economic-project.json'));\nevent('research-resume','click',async()=>{const original=getState()?.pending;if(original?.kind?.startsWith('research-')){pending=null;await api('/api/action',{action:original.kind,id:original.id,expectedRevision:original.expectedRevision,projectId:getState().id,resume:true});await refresh();await load();}else if(pending){const result=await api('/api/action',pending,pending.projectId);pending=null;await refresh();await load();}else throw new Error('No original research action is pending.');});\naddRequirement();return {onState(){const state=getState();if(!state)return;if(projectId!==state.id){projectId=state.id;generation++;loading++;readEntry++;pending=null;entry=null;view=null;offset=0;lastStateRevision=null;clearEntry();$('research-product-form').reset();$('research-product-id').readOnly=false;$('research-requirements').replaceChildren();addRequirement();$('research-product-select').replaceChildren();$('research-filter').reset();}if(state.revision!==lastStateRevision){lastStateRev