      "content": "#!/usr/bin/env node\n// MIT. Compose one exact additive source packet into a selected private donor copy.\nimport {readFile,writeFile,mkdir,lstat,rename} from 'node:fs/promises';\nimport {resolve,join,dirname,relative,isAbsolute} from 'node:path';\nimport {createHash,randomUUID} from 'node:crypto';\nconst sha=b=>createHash('sha256').update(b).digest('hex');\nconst [rootArgument,packetArgument]=process.argv.slice(2);\nif(!rootArgument||!packetArgument)throw Error('Usage: node compose-research.mjs PRIVATE_DONOR_ROOT COMPLETE_SOURCE_PACKET.json');\nconst root=resolve(rootArgument),packet=JSON.parse(await readFile(resolve(packetArgument),'utf8'));\nif(packet.operation_id!=='ESI-RESEARCH-CATALOG-4593-20261013'||!Array.isArray(packet.files))throw Error('Select the original complete catalogue source packet.');\nconst pending=[];\nfor(const file of packet.files){if(file.role==='native-input'||file.role==='operator')continue;\nif(!file.path||isAbsolute(file.path)||file.path.split('/').some(p=>!p||p==='.'||p==='..'))throw Error('Invalid complete source path');\nconst destination=join(root,file.path),rel=relative(root,destination);if(rel.startsWith('..')||isAbsolute(rel))throw Error('Source path escaped donor');\nconst bytes=Buffer.from(file.content,'utf8');if(bytes.length!==file.bytes||sha(bytes)!==file.sha256)throw Error('Incoming source changed: '+file.path);\nlet current=null;try{const info=await lstat(destination);if(!info.isFile()||info.isSymbolicLink())throw Error('Expected ordinary donor file: '+file.path);current=await readFile(destination);}catch(e){if(e.code!=='ENOENT')throw e;}\nif(current&&sha(current)===file.sha256)continue;\nconst permitted=[file.before_sha256,...(file.before_sha256_alternatives??[])].filter(Boolean);\nif(current&&!permitted.includes(sha(current)))throw Error('Current donor changed; compose its whole current source before writing: '+file.path);\nif(!current&&file.before_sha256)throw Error('Missing maintained donor source: '+file.path);\npending.push({file,destination,bytes});}\nfor(const item of pending){await mkdir(dirname(item.destination),{recursive:true,mode:0o700});const temporary=item.destination+'.research-'+randomUUID();await writeFile(temporary,item.bytes,{flag:'wx',mode:0o600});await rename(temporary,item.destination);}\nconsole.log(JSON.stringify({operation:packet.operation_id,sourceRoot:root,changed:pending.map(x=>x.file.path),received:packet.files.filter(f=>!['native-input','operator'].includes(f.role)).length}));\n",
