lar/scf-starforge-20261009/sf30-seller-sdk/fred/operating/files.mjs\",\n    \"stellar/scf-starforge-20261009/sf30-seller-sdk/fred/operating/archive-io.mjs\",\n    \"stellar/scf-starforge-20261009/sf30-seller-sdk/fred/operating/ARCHIVE.md\",\n    \"stellar/scf-starforge-20261009/sf30-seller-sdk/fred/operating/http.mjs\",\n    \"stellar/scf-starforge-20261009/sf30-seller-sdk/fred/ui/operating.js\",\n    \"stellar-forge/mcp-merchant-operator/fred-research.mjs\",\n    \"stellar-forge/mcp-merchant-operator/catalog/fred-research.mjs\",\n    \"stellar-forge/mcp-merchant-operator/fred-research-journey.mjs\",\n    \"stellar-forge/mcp-merchant-operator/FRED_RESEARCH_WORKSPACE.md\"\n  ],\n  \"merchantProviders\": {\n    \"fred-workspaces\": \"stellar-forge/mcp-merchant-operator/providers/fred-workspaces.mjs\"\n  }\n}\n",
