      "content": "{\n  \"schema\": \"commons.mtc-catalogue-import.v1\",\n  \"operation\": \"MTC-PBA2050PLUS-SOURCE-IMPORT-20261013\",\n  \"maintainedSource\": {\n    \"repository\": \"woahwhattheheck/tjlabs-stellar-merchant-workspace\",\n    \"merge\": \"7edb84dd26c6bd425fcdf21f66a084ec3569d67f\",\n    \"componentSha256\": \"7ae75dd791fdfd80901d80a7ffee98b0ffe93a28025ca24ffc39e5eb551d2692\"\n  },\n  \"definitions\": [\n    {\n      \"entryId\": \"mtc-pba2050plus-final-2024-12-17\",\n      \"title\": \"Plan Bay Area 2050+: Final Regional Growth Forecast\",\n      \"publisher\": \"Metropolitan Transportation Commission / Association of Bay Area Governments\",\n      \"url\": \"https://mtc.ca.gov/sites/default/files/meetings/attachments/6172/6biv_24_1482_Attachment_C_Final_Regional_Growth_Forecast_5.pdf?cb=2b452fe1\",\n      \"kind\": \"REPORT\",\n      \"topics\": [\n        \"population\",\n        \"households\",\n        \"housing\",\n        \"employment\",\n        \"regional forecasts\"\n      ],\n      \"geographies\": [\n        \"Nine-county San Francisco Bay Area\"\n      ],\n      \"cadenceDays\": null,\n      \"expectedRelease\": null,\n      \"licence\": \"Agency public meeting attachment. Retain its original attribution and source document; no additional reuse licence is asserted.\",\n      \"notes\": \"Original December 17, 2024 meeting attachment, two pages. Table 1 on page 2 contains four regional series and seven labelled years (2020–2050). It is the published 2050+ forecast background, not an issued 2060 procurement specification. Source notes a 2023 plan base year although the table begins 2020. All nine counties are covered as one aggregate; this table does not supply county allocations. Historical/forecast roles are preserved as published; no blanket assertion that 2020 or 2025 is an observed actual. Original retained PDF: 152,937 bytes.\",\n      \"retired\": false\n    },\n    {\n      \"entryId\": \"mtc-pba2050plus-faq-2026-02-12\",\n      \"title\": \"Plan Bay Area 2050+: Regional Growth Forecast FAQ\",\n      \"publisher\": \"Metropolitan Transportation Commission / Association of Bay Area Governments\",\n      \"url\": \"https://mtc.ca.gov/sites/default/files/meetings/attachments/6502/8aiv_26_0110_After_Meeting_Handout_PBA_2050_Plus_Regional_Growth_Forecast_FAQ_February_2026.pdf?cb=d0e49206\",\n      \"kind\": \"METHOD\",\n      \"topics\": [\n        \"regional forecasts\",\n        \"methodology\",\n        \"population\",\n        \"employment\"\n      ],\n      \"geographies\": [\n        \"Nine-county San Francisco Bay Area\"\n      ],\n      \"cadenceDays\": null,\n      \"expectedRelease\": null,\n      \"licence\": \"Agency public meeting handout. Retain its original attribution and source document; no additional reuse licence is asserted.\",\n      \"notes\": \"Original February 12, 2026 meeting handout, four pages, 777,707 bytes. Explains the adopted 2050+ growth forecast and the next major Plan Bay Area 2060 cycle. Used as published methodological background. The separate 2060 RFP, question deadlines, addenda, evaluation and contract terms must come from the issued procurement documents.\",\n      \"retired\": false\n    },\n    {\n      \"entryId\": \"mtc-pba2050plus-table1-2024-12-17\",\n      \"title\": \"Plan Bay Area 2050+: complete published Table 1 transcription\",\n      \"publisher\": \"MTC / ABAG (published values); TJLabs (source-labelled transcription)\",\n      \"url\": \"https://mtc.ca.gov/sites/default/files/meetings/attachments/6172/6biv_24_1482_Attachment_C_Final_Regional_Growth_Forecast_5.pdf?cb=2b452fe1\",\n      \"kind\": \"DATASET\",\n      \"topics\": [\n        \"population\",\n        \"households\",\n        \"housing\",\n        \"employment\",\n        \"regional forecasts\"\n      ],\n      \"geographies\": [\n        \"Nine-county San Francisco Bay Area\"\n      ],\n      \"cadenceDays\": null,\n      \"expectedRelease\": null,\n      \"licence\": \"Source-label